-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'BANCO DE DADOS' and a.numero = 5
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 5 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 05', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 05 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/BANCO-DE-DADOS/ATIVIDADES/ATIVIDADE-PRATICA-AULA-05.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Diga qual é a demanda dita pela cliente.', 0.2, '"Uma **planilha online** para os banhos."', 'Nota cheia (0,2): cita a planilha online. Zero (0): confunde com a necessidade.'),
      (v_atividade, 1, 2, 'Explique qual é a necessidade real dela, usando os fatos descobertos.', 0.4, 'Ela precisa **controlar a agenda sem conflito de horários**, **lembrar os clientes** dos agendamentos e **saber quanto recebeu** no mês (registrar serviços e pagamentos).', 'Nota cheia (0,4): necessidade ligada aos três fatos. Metade (0,2): um ou dois fatos. Zero (0): repete "planilha online".'),
      (v_atividade, 1, 3, 'Explique por que o banco deve ser modelado pela necessidade e não pela frase inicial.', 0.4, 'Porque a frase inicial é uma **solução imaginada** pela cliente; se o banco seguir só a frase, **não resolve o problema** (conflitos, esquecimentos, controle financeiro) e precisará ser refeito.', 'Nota cheia (0,4): solução × problema + consequência. Metade (0,2): só um dos dois. Zero (0): defende seguir a frase.'),
      (v_atividade, 2, 1, 'Indique uma técnica de levantamento para a diretora e outra para os 300 alunos.', 0.2, 'Diretora: **entrevista**. 300 alunos: **questionário**.', 'Nota cheia (0,2): as duas. Metade (0,1): uma. Zero (0): nenhuma.'),
      (v_atividade, 2, 2, 'Explique como usar a observação com a secretaria e o que ela revela que a entrevista talvez não revele.', 0.4, 'Acompanhar a secretaria **durante a rotina** (matrículas, atendimentos), anotando sem atrapalhar. Revela **como o trabalho é feito de verdade**: passos esquecidos, anotações paralelas, dados que ninguém citou na entrevista.', 'Nota cheia (0,4): como fazer + o que revela. Metade (0,2): só um. Zero (0): sem relação com observação.'),
      (v_atividade, 2, 3, 'Explique como a análise das fichas de papel ajuda a descobrir os dados do banco, com um exemplo.', 0.4, '**Cada campo** da ficha é um **dado candidato** do banco. Ex.: a ficha tem nome, CPF, data de nascimento, curso, turno e responsável → candidatos a atributos de aluno, matrícula e responsável.', 'Nota cheia (0,4): explicação + exemplo com campos. Metade (0,2): só a explicação. Zero (0): sem relação.'),
      (v_atividade, 3, 1, 'Escreva duas perguntas abertas sobre o que precisa ser registrado.', 0.2, 'Exemplos: "O que vocês **registram** de cada aluno quando ele entra?"; "O que é **anotado** em cada treino e quem anota?"', 'Nota cheia (0,2): duas perguntas abertas sobre registro. Metade (0,1): uma, ou perguntas fechadas (sim/não). Zero (0): perguntas sem relação com dados.'),
      (v_atividade, 3, 2, 'Escreva uma pergunta sobre regras de negócio e uma sobre quem pode ver cada informação, explicando o que cada uma ajuda a descobrir.', 0.4, 'Regras: "Quais **regras nunca podem ser quebradas**?" (ex.: aluno sem exame não treina) — descobre restrições do banco. Acesso: "**Quem pode ver** cada informação?" — descobre permissões e dados pessoais a proteger.', 'Nota cheia (0,4): duas perguntas + o que cada uma descobre. Metade (0,2): uma pergunta explicada. Zero (0): perguntas sem relação.'),
      (v_atividade, 3, 3, 'Escreva uma pergunta sobre volume e histórico e explique como a resposta influencia o banco.', 0.4, '"Quantos alunos e treinos são registrados **por mês** e **por quanto tempo** guardar o histórico?" A resposta define **espaço em disco**, **backup**, **índices** e se é preciso **arquivar** dados antigos.', 'Nota cheia (0,4): pergunta + influência. Metade (0,2): só um. Zero (0): sem relação.'),
      (v_atividade, 4, 1, 'Escreva um requisito de dados a guardar.', 0.2, '"Guardar **nome, CPF e telefone** de cada aluno."', 'Nota cheia (0,2): requisito de dados a guardar. Zero (0): outro tipo.'),
      (v_atividade, 4, 2, 'Escreva um requisito de acesso e um de consulta/relatório, de forma verificável.', 0.4, 'Acesso: "O **instrutor consulta somente os alunos vinculados a ele**." Consulta: "**Listar os alunos com mensalidade vencida e não paga**, com o valor e a data de vencimento."', 'Nota cheia (0,4): os dois, verificáveis. Metade (0,2): um verificável, ou dois vagos. Zero (0): nenhum.'),
      (v_atividade, 4, 3, 'Explique o que torna um requisito verificável e reescreva "o sistema tem que ser rápido" de forma verificável.', 0.4, 'É verificável quando dá para **testar objetivamente** se foi cumprido. Ex.: "A consulta de alunos de um instrutor responde em **até 2 segundos** com **5 mil alunos** cadastrados."', 'Nota cheia (0,4): definição + reescrita com medida. Metade (0,2): só um. Zero (0): reescrita ainda vaga.'),
      (v_atividade, 5, 1, 'Classifique os quatro requisitos por tipo.', 0.2, '(1) **volume e histórico**; (2) **qualidade**; (3) **regra de negócio**; (4) **consulta/relatório**.', 'Nota cheia (0,2): os quatro. Metade (0,1): três. Zero (0): dois ou menos.'),
      (v_atividade, 5, 2, 'Explique como os substantivos e características do pedido viram entidades e atributos, com exemplos da escola.', 0.4, '**Substantivos** importantes (aluno, turma, curso, matrícula) são candidatos a **entidades**; **características** (nome, CPF, data de nascimento, turno) são candidatas a **atributos**.', 'Nota cheia (0,4): as duas regras com exemplos da escola. Metade (0,2): uma regra ou sem exemplos. Zero (0): invertido.'),
      (v_atividade, 5, 3, 'Explique como o requisito 1 influencia decisões sobre disco e backup.', 0.4, 'Guardar **5 anos** de histórico aumenta o **volume**: é preciso prever **espaço em disco** para os dados e **backups** do período, além de definir por quanto tempo os backups ficam guardados.', 'Nota cheia (0,4): disco + backup ligados ao período. Metade (0,2): só um. Zero (0): sem relação.'),
      (v_atividade, 6, 1, 'Diga o recurso do banco que garante a regra do CPF.', 0.2, 'Restrição **UNIQUE** no CPF.', 'Nota cheia (0,2): UNIQUE. Zero (0): outro recurso.'),
      (v_atividade, 6, 2, 'Explique os recursos que garantem as regras da matrícula e da mensalidade.', 0.4, 'Matrícula: **chaves estrangeiras** para aluno e turma (não aceita matrícula de aluno ou turma inexistente). Mensalidade: restrição **CHECK** (valor > 0).', 'Nota cheia (0,4): os dois recursos corretos explicados. Metade (0,2): um. Zero (0): nenhum.'),
      (v_atividade, 6, 3, 'Explique o recurso que garante o registro de quem alterou a nota e por que isso protege a escola.', 0.4, '**Trigger de auditoria**: a cada alteração de nota, grava automaticamente quem alterou, quando e os valores antigo e novo. Protege a escola porque permite **descobrir e provar alterações indevidas**.', 'Nota cheia (0,4): trigger + proteção. Metade (0,2): só o recurso. Zero (0): recurso errado.'),
      (v_atividade, 7, 1, 'Liste o que entra no escopo da primeira versão.', 0.2, '**Alunos, responsáveis, cursos, turmas, matrículas e pagamentos** (mensalidades).', 'Nota cheia (0,2): itens das matrículas coerentes. Metade (0,1): parcial. Zero (0): inclui cantina e folha.'),
      (v_atividade, 7, 2, 'Liste o que não entra e explique por que registrar isso no documento.', 0.4, 'Não entra: **cantina** e **folha de pagamento**. Registrar evita **pedidos extras sem controle** e deixa claro para o cliente o que será entregue no prazo.', 'Nota cheia (0,4): itens + motivo do registro. Metade (0,2): só um. Zero (0): diz que não precisa registrar.'),
      (v_atividade, 7, 3, 'Escreva o objetivo do escopo em uma frase e explique quem são as partes interessadas.', 0.4, 'Ex.: "O banco vai **registrar alunos, turmas, matrículas e pagamentos** para que a escola **não perca matrículas e saiba as vagas e os pagamentos**." Partes interessadas: **diretora** (pede e aprova), **secretaria** (usa), **professores e alunos** (usam/consultam), **equipe** que desenvolve.', 'Nota cheia (0,4): objetivo com o quê e por quê + partes. Metade (0,2): só um dos dois. Zero (0): objetivo técnico sem relação.'),
      (v_atividade, 8, 1, 'Liste as entregas do projeto de banco de dados.', 0.2, '**Documento de escopo/requisitos, modelo de entidades, DER, tabelas normalizadas, padrão de dados, scripts SQL e documentação técnica**.', 'Nota cheia (0,2): três ou mais entregas. Metade (0,1): duas. Zero (0): entregas sem relação.'),
      (v_atividade, 8, 2, 'Escreva uma premissa e explique o que acontece se ela não for verdadeira.', 0.4, 'Ex.: "A **diretora estará disponível** uma vez por semana para validar o modelo." Se não for verdade, as **validações atrasam** e o projeto pode seguir com **erros de entendimento**.', 'Nota cheia (0,4): premissa + consequência. Metade (0,2): só um. Zero (0): confunde com requisito.'),
      (v_atividade, 8, 3, 'Escreva dois riscos do projeto com uma ação para reduzir cada um.', 0.4, 'Ex.: (1) **mudanças de escopo frequentes** → registrar e aprovar cada mudança; (2) **dados das fichas antigas com erros** → separar tempo para limpeza e padronização; (3) **atraso de entregas** → prazos internos e acompanhamento semanal.', 'Nota cheia (0,4): dois riscos com ação. Metade (0,2): um risco com ação ou dois sem ação. Zero (0): sem riscos coerentes.'),
      (v_atividade, 9, 1, 'Diga se o pedido é mudança de escopo ou requisito esquecido e justifique.', 0.2, '**Mudança de escopo**: a cantina já tinha sido colocada **fora do escopo**; é um pedido novo, não um requisito esquecido.', 'Nota cheia (0,2): classificação + justificativa. Metade (0,1): só a classificação. Zero (0): requisito esquecido.'),
      (v_atividade, 9, 2, 'Explique os passos para tratar a mudança de escopo.', 0.4, '**Registrar o pedido**, avaliar o **impacto** (tabelas novas, prazo, custo), apresentar à diretora e só incluir com **aprovação** (ou deixar para uma **próxima versão**).', 'Nota cheia (0,4): registrar + impacto + aprovação. Metade (0,2): dois passos. Zero (0): incluir direto.'),
      (v_atividade, 9, 3, 'Explique o que acontece com um projeto em que pedidos assim entram sem registro.', 0.4, 'O projeto **cresce sem controle**, **atrasa**, a equipe perde o foco e o cliente fica insatisfeito porque o combinado inicial não é entregue.', 'Nota cheia (0,4): crescimento sem controle + atraso/consequência. Metade (0,2): só "atrasa". Zero (0): diz que melhora.'),
      (v_atividade, 10, 1, 'Diga por que o grupo precisa organizar o tempo das entregas.', 0.2, 'Porque as entregas são **semanais e dependentes** (uma depende da anterior); sem organização, uma atrasada **atrasa todas**.', 'Nota cheia (0,2): dependência entre entregas. Metade (0,1): "para não atrasar". Zero (0): sem relação.'),
      (v_atividade, 10, 2, 'Explique como dividir as tarefas e definir prazos internos.', 0.4, 'Dividir as tarefas **por pessoa** (ou em duplas) conforme cada entrega, definir **prazos internos alguns dias antes** do prazo do professor e reservar tempo para **revisão em grupo**.', 'Nota cheia (0,4): divisão + prazo interno antecipado. Metade (0,2): só um. Zero (0): uma pessoa faz tudo.'),
      (v_atividade, 10, 3, 'Explique como registrar o andamento e o que fazer quando uma entrega atrasar.', 0.4, 'Registrar num **quadro de tarefas** (ou planilha) quem faz o quê, prazo e situação. Se atrasar: **avisar logo o grupo**, redistribuir tarefas ou pedir ajuda ao professor, e **ajustar o cronograma**.', 'Nota cheia (0,4): forma de registro + ação no atraso. Metade (0,2): só um. Zero (0): esconder o atraso.');
end $$;
